// index.mjs —— Node.js 异步编程三种写法对比
// 运行方式：node index.mjs

import { readFile, writeFile } from 'node:fs/promises';
import { readFile as readFileByCallback } from 'node:fs';
import { setTimeout as delay } from 'node:timers/promises';

// ========== 0. 准备一个测试文件（保证示例可直接运行） ==========
await writeFile('./demo.txt', 'Hello Node.js\n今天学习 Promise 与 async/await');

// ========== 1. 回调写法（Callback） ==========
readFileByCallback('./demo.txt', 'utf8', (err, data) => {
  // 回调的第一个参数永远是 error（Error-First 约定）
  if (err) {
    console.error('[回调] 读取失败:', err.message);
    return;
  }
  console.log('[回调] 读取成功:', data.split('\n')[0]);
});

// ========== 2. Promise 写法 ==========
const firstLine = await readFile('./demo.txt', 'utf8')
  .then((text) => text.split('\n')[0])   // 成功时转换数据
  .catch((e) => `出错了: ${e.message}`); // 任一环节失败都会走到这里
console.log('[Promise] 第一行是:', firstLine);

// ========== 3. async/await 写法（推荐） ==========
async function copyWithSummary(srcPath, destPath) {
  try {
    const text = await readFile(srcPath, 'utf8');
    const summary = `字符数: ${text.length}，行数: ${text.split('\\n').length}`;
    await writeFile(destPath, summary);
    console.log('[await] 摘要已写入', destPath, '->', summary);
    return summary;
  } catch (err) {
    // 统一的错误处理，比每层写 .catch() 清爽很多
    console.error('[await] 处理失败:', err.code || err.message);
    return null;
  }
}

await copyWithSummary('./demo.txt', './summary.txt');

// ========== 4. 串行 vs 并行（性能关键点） ==========
console.time('串行耗时');
await delay(200); // 假装是第一个 IO 请求
await delay(200); // 必须等第一个做完才开始
console.timeEnd('串行耗时'); // 约 400ms+

console.time('并行耗时');
await Promise.all([delay(200), delay(200)]); // 两个请求同时发出
console.timeEnd('并行耗时'); // 约 200ms+

// ========== 5. 小提醒：async 函数返回值会被自动包装成 Promise ==========
async function getName() {
  return 'Alice';
}
const maybeName = getName();
console.log('[注意] 没有 await 时拿到的是 Promise:', maybeName);
console.log('[注意] 加上 await 才是值:', await maybeName);

